import React from "react";

const reportsList = [
  { id: 1, title: "Rapport d'activité hebdomadaire", description: "Synthèse de la semaine." },
  { id: 2, title: "Rapport mensuel", description: "Analyse du mois." },
  { id: 3, title: "Rapport fiscal", description: "Export fiscal." },
];

export default function ReportsList() {
  return (
    <section
      style={{
        background: "#fff",
        borderRadius: 24,
        padding: 32,
        marginBottom: 32,
        width: "100%",
        maxWidth: 700,
        boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
      }}
    >
      <h2 style={{ color: "#222", fontSize: 22, marginBottom: 18 }}>Liste des rapports générés</h2>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {reportsList.map((report) => (
          <li
            key={report.id}
            style={{
              marginBottom: 18,
              background: "#DBDFE0",
              borderRadius: 18,
              padding: 18,
            }}
          >
            <div>
              <h3 style={{ color: "#1a7f6b", fontSize: 18, margin: 0 }}>{report.title}</h3>
              <p style={{ color: "#444", margin: 0 }}>{report.description}</p>
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
}